import {createRecordedSpeaker} from './recorded-speech.js';
import {createSpeaker,englishVoices,selectVoice} from './speech.js';
import {createSync} from './sync-state.js';
import {STORAGE_KEY,DAY,localDay,initialState,normalizeState,todayStats,makeSession,currentTask,prepareAnswer,correctPending,continueSession,useHint,groupComplete,sessionComplete,bookProgress,sessionKey,reconcileSession,groupWords,reorderLegacyNewSession} from './core.js';

const BUILD=window.JIQIAO_BUILD||{mode:'hosted',platform:'web',version:'1.0.0'};
const OFFLINE=BUILD.mode==='offline',NATIVE=BUILD.platform==='android';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4zM13 6a3 3 0 0 1 3-3h5v16h-4a4 4 0 0 0-4 2',root:'M12 21V10M12 14C4 15 3 9 4 5c6-1 9 4 8 9ZM12 11c0-7 5-8 9-7 1 5-3 9-9 7',chart:'M4 20h17M7 16V9M12 16V4M17 16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'m21 21-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',star:'m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.3-5.7-3-5.7 3 1.1-6.3L2.8 9.7l6.4-.9z',volume:'m11 4-5 4H3v8h3l5 4zM15 8c2 2 2 6 0 8M18 5c4 4 4 10 0 14',refresh:'M20 10a8 8 0 0 0-14-5L3 8M3 3v5h5M4 14a8 8 0 0 0 14 5l3-3M21 21v-5h-5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 11v6M12 7v1',device:'M4 3h16v13H4zM9 21h6M12 16v5',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',back:'m14 6-6 6 6 6',flag:'M5 21V3h13l-2 4 2 4H5',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 11v2',leaf:'M4 20C1 10 8 3 21 3c0 13-7 20-17 17ZM4 20 15 9'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
let db,state,view='today',bookFilter='全部',rootFilter='全部',query='',rootQuery='',toastTimer,notes={},pendingBackup=null,storageOkay=true,cardStarted=Date.now(),noteTimes={},syncer,syncStatus={kind:'waiting',message:'准备同步…'},storageBlocked=false;
const app=$('#app'),modal=$('#modal');
const label={today:'今日学习',books:'我的词书',roots:'词根词典',stats:'学习记录',settings:'我的',search:'查找单词',favorites:'我的生词本',plan:'学习计划',summary:'学习完成',study:'专注学习'};
const fmt=n=>Number(n).toLocaleString('zh-CN');
const book=()=>db.books.find(b=>b.id===state.book)||db.books[0];
const getBook=id=>id==='custom'?{id:'custom',title:'自定义词表',level:'CUSTOM',kind:'自定义',color:'purple',words:state.custom,description:'自己选择，按自己的节奏学习。',criteria:'由你导入或在单词详情中添加的词汇。'}:id==='favorites'?{id:'favorites',title:'我的生词本',words:state.favorites,level:'SAVED',kind:'收藏',color:'orange',description:'把值得再看一次的单词收在这里。',criteria:'你主动收藏的单词。'}:db.books.find(b=>b.id===id);
const activeBook=()=>getBook(state.book)||db.books[0];
const ids=()=>activeBook().words;
const dueIds=()=>{const pool=state.settings.maintainAll?Object.keys(state.progress):ids();return pool.filter(w=>db.words[w]&&!state.progress[w]?.known&&state.progress[w]?.due<=Date.now());};
const rootOf=w=>db.roots.find(r=>r.id===(db.words[w]?.studyRoot||db.words[w]?.root));
function save(queue=true){if(storageBlocked){toast('原记录读取异常，已保留原文件，请先恢复备份。');return;}try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOkay=true;if(queue)syncer?.queue();}catch{storageOkay=false;toast('浏览器无法保存进度，请及时导出备份。');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function showModal(title,html){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();}
function navigate(next){speaker.stop();view=next;query='';render();window.scrollTo(0,0);}
function shell(content){
 const nav=[['today','home','学习'],['plan','chart','计划'],['books','book','词库'],['settings','settings','我的']];
 const studying=view==='study';document.body.className=`theme-${state.settings.theme}${studying?' study-mode':''}`;
 const selected=['stats'].includes(view)?'plan':['roots','favorites','search'].includes(view)?'books':view;
 return `<div class="shell"><header class="app-header"><button class="wordmark" data-action="nav" data-id="today"><span class="brand-mark"><img src="./icon.svg" alt=""></span>记巧<span class="wordmark-en">JIQIAO</span></button><div class="header-actions"><button class="icon-btn" data-action="nav" data-id="search" aria-label="查词">${icon('search')}</button><button class="icon-btn" data-action="nav" data-id="settings" aria-label="学习设置">${icon('settings')}</button></div></header><main class="main ${view==='today'?'home-main':''}">${storageBlocked?'<div class="notice recovery-warning">原记录读取异常，已保留原数据。请在“我的”恢复备份后继续学习。</div>':''}${!storageOkay?'<div class="notice recovery-warning">本机保存未成功，请立即导出备份。</div>':''}${content}</main>${!studying?`<nav class="app-nav" aria-label="主要导航">${nav.map(([id,ic,txt])=>`<button data-action="nav" data-id="${id}" class="${selected===id?'active':''}" ${selected===id?'aria-current="page"':''}>${icon(ic)}<span>${txt}</span></button>`).join('')}</nav>`:''}</div>`;
}
function weekData(){return Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const day=localDay(d);return {day,label:['日','一','二','三','四','五','六'][d.getDay()],value:new Set(state.events.filter(e=>e.day===day).map(e=>e.word)).size};});}
function weekChart(){const days=weekData(),max=Math.max(5,...days.map(d=>d.value));return `<div class="week-bars" role="img" aria-label="最近七天学习单词数：${days.map(d=>`${d.day} ${d.value}词`).join('，')}">${days.map((d,i)=>`<div class="bar-wrap"><span class="bar-value">${d.value||''}</span><div class="bar ${i===6?'today':''}" style="height:${Math.max(3,d.value/max*90)}%"></div><span>${i===6?'今天':d.label}</span></div>`).join('')}</div>`;}
function rootFeature(){const inBook=new Set(ids());const r=db.roots.find(r=>r.words.some(w=>inBook.has(w.word)&&!state.progress[w.word]))||db.roots[0];if(!r)return '';const ws=r.words.filter(w=>inBook.has(w.word));return `<div class="root-feature"><div class="root-glyph">${esc(r.label)}</div><div class="root-copy"><div class="between"><h3>${esc(r.meaning)}</h3><button class="text-btn" data-action="root" data-id="${r.id}">看看词族</button></div><p>${esc(r.intro)}</p><div class="word-chips">${(ws.length?ws:r.words).slice(0,4).map(w=>`<button class="word-chip" data-action="word" data-id="${esc(w.word)}">${esc(w.word)}</button>`).join('')}</div></div></div>`;}
function dashboard(){
 const b=activeBook(),stats=todayStats(state),pending=state.session&&!sessionComplete(state.session)?state.session:Object.values(state.parked).find(s=>!sessionComplete(s));
 const remaining=ids().filter(w=>!state.progress[w]),n=Math.min(remaining.length,Math.max(0,state.goal-stats.newCount)),due=dueIds().length;
 const preview=makeSession(state,ids(),db.words,{mode:'new'}),word=preview?.words[0]||remaining[0]||ids()[0],d=db.words[word],root=rootOf(word);
 return `<section class="learning-home"><div class="home-overline"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><span>让单词有迹可循</span></div><div class="daily-word">${root?`<button class="daily-root" data-action="root" data-id="${root.id}">${esc(root.label)}<span>${esc(root.meaning)}</span></button>`:'<span class="daily-root">词汇理解与回忆</span>'}${d?`<button class="featured-word" data-action="word" data-id="${esc(word)}">${esc(word)}</button><p class="featured-phonetic">${d.phonetic?'/'+esc(d.phonetic)+'/':''}<button data-action="speak" data-id="${esc(word)}" aria-label="朗读 ${esc(word)}">${icon('volume')}</button></p><p class="featured-meaning">${esc(d.meaning)}</p><p class="featured-memory">${esc(d.lesson?.explanation||(root?'结合构词核心义理解，逐词核对实际释义。':'结合释义与英文解释记忆，逐次检验是否能独立回忆。'))}</p>`:'<p>当前词表还没有单词，可在词库中选择词书。</p>'}${root?`<div class="home-siblings">${root.words.filter(e=>ids().includes(e.word)&&e.word!==word).slice(0,3).map(e=>`<button data-action="word" data-id="${esc(e.word)}">${esc(e.word)}</button>`).join('')}</div>`:''}</div><div class="home-bottom"><button class="current-book" data-action="nav" data-id="plan">${icon('book')}<span>${esc(b.title)}</span>${icon('chevron')}</button>${pending?`<button class="resume-strip" data-action="resume">继续${esc(getBook(pending.book)?.title||pending.title)}的${pending.mode==='review'?'复习':'学习'} · ${pending.words.filter(w=>pending.items[w].done).length}/${pending.words.length} 词</button>`:''}<div class="home-actions"><button class="learn-entry" data-action="start" data-mode="new"><span class="entry-count">${n}<small>今日待学</small></span><span class="entry-name">学习新词</span><span class="entry-label">从词根建立联系</span><i></i></button><span class="action-divider"></span><button class="learn-entry" data-action="start" data-mode="review"><span class="entry-count">${due}<small>到期复习</small></span><span class="entry-name">到期复习</span><span class="entry-label">把记忆留下来</span><i></i></button></div><div class="home-progress"><span>今日已学 ${stats.newCount}</span><span>已复习 ${stats.reviewCount}</span><button data-action="nav" data-id="plan">查看计划</button></div>${!state.settings.maintainAll?'<p class="footnote">当前只复习本书；可在“我的”开启所有词书复习。</p>':''}</div></section>`;
}

function planPage(){
 const b=activeBook(),p=bookProgress(state,ids()),stats=todayStats(state),days=weekData(),max=Math.max(5,...days.map(d=>d.value));
 const now=new Date(),year=now.getFullYear(),month=now.getMonth(),first=new Date(year,month,1).getDay(),count=new Date(year,month+1,0).getDate();
 return `<div class="page-head"><h1>学习计划</h1><button class="text-btn" data-action="nav" data-id="settings">学习设置</button></div><section class="plan-book"><div class="between"><h2>正在学习</h2><button class="text-btn" data-action="nav" data-id="books">换本词书</button></div><div class="book-top">${cover(b)}<div class="book-title"><h3>${esc(b.title)}</h3><p>已学习 ${fmt(p.learned)} / ${fmt(p.total)}</p><div class="progress"><i style="width:${p.percent}%"></i></div></div></div><div class="plan-numbers"><div><strong>${Math.max(0,state.goal-stats.newCount)}</strong><span>今日待学</span></div><div><strong>${dueIds().length}</strong><span>待复习</span></div><button data-action="goal"><strong>${state.goal}</strong><span>每日新词 ${icon('settings')}</span></button></div><p class="book-meta">本书 ${b.words.filter(w=>db.words[w]?.root).length} 词附构词关联 · ${b.words.filter(w=>db.words[w]?.lesson).length} 词有完整讲解</p></section><div class="plan-grid"><section class="panel"><div class="panel-head"><h2>我的数据</h2><button class="text-btn" data-action="nav" data-id="stats">详细记录</button></div><div class="data-numbers"><div><strong>${Object.keys(state.progress).length}</strong><span>累计学习</span></div><div><strong>${new Set(state.events.map(e=>e.day)).size}</strong><span>学习天数</span></div><div><strong>${state.checkins.length}</strong><span>完成打卡</span></div></div>${weekChart()}</section><section class="panel"><div class="panel-head"><h2>${year} 年 ${month+1} 月</h2><span class="small">学习日历</span></div><div class="calendar">${['日','一','二','三','四','五','六'].map(x=>`<span class="weekday">${x}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:count},(_,i)=>{const n=i+1,key=`${year}-${String(month+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`,learned=state.events.some(e=>e.day===key),checked=state.checkins.includes(key);return `<span class="calendar-day ${learned?'studied':''} ${n===now.getDate()?'current':''}" title="${key}${checked?' 已打卡':learned?' 已学习':''}">${n}${checked?'<i></i>':''}</span>`;}).join('')}</div></section></div><section class="panel content-links"><button data-action="book-detail" data-id="${esc(b.id)}">${icon('book')}当前词表${icon('chevron')}</button><button data-action="nav" data-id="favorites">${icon('star')}我的生词本${icon('chevron')}</button><button data-action="nav" data-id="roots">${icon('root')}词根词典${icon('chevron')}</button></section>`;
}
function cover(b){return `<div class="cover ${esc(b.color||'green')}" aria-hidden="true"><small>ROOTWISE</small><span class="serif">${esc(b.level)}</span><small>${esc(b.kind)}词汇</small></div>`;}
function booksPage(){const list=db.books.filter(b=>bookFilter==='全部'||b.level===bookFilter);return `<div class="page-head"><div><h1>选择词书</h1><p>词书决定学习范围，词根帮助你建立联系。</p></div><button class="button secondary" data-action="import-words">${icon('plus')}导入词表</button></div><div class="toolbar"><div class="tabs inset">${['全部','CET-4','CET-6','ROOTS'].map(t=>`<button data-action="book-filter" data-id="${t}" class="${bookFilter===t?'active':''}">${{全部:'全部词书','CET-4':'四级','CET-6':'六级',ROOTS:'词根精选'}[t]}</button>`).join('')}</div><button class="text-btn" data-action="sources">${icon('info')} 词书来源与说明</button></div><div class="book-grid">${list.map(b=>{const p=bookProgress(state,b.words);return `<article class="book-card ${state.book===b.id?'selected':''}"><div class="book-top">${cover(b)}<div class="book-title"><h3>${esc(b.title)}</h3><p>${fmt(b.words.length)} 个单词</p><div style="margin-top:7px"><span class="pill ${state.book===b.id?'':'neutral'}">${state.book===b.id?'正在学习':b.kind==='常用'?'通用词频':b.kind==='全部'?'含基础词':'自编精选'}</span></div></div></div><p>${esc(b.description)}</p><div class="book-meta">构词关联 ${b.rootCount} 词 · 完整讲解 ${b.lessonCount} 词</div><div class="progress"><i style="width:${p.percent}%"></i></div><div class="book-bottom"><button class="text-btn" data-action="book-detail" data-id="${b.id}">查看词表</button><button class="button ${state.book===b.id?'ghost':'secondary'} sm" data-action="choose-book" data-id="${b.id}">${state.book===b.id?'继续学习':'选择词书'}</button></div></article>`;}).join('')}</div><div class="section-head"><h2>自己的小书架</h2></div><div class="book-grid">${['favorites','custom'].map(id=>{const b=getBook(id);return `<article class="book-card"><div class="flex"><div class="empty-icon">${icon(id==='favorites'?'star':'book')}</div><h3>${b.title}</h3><span class="pill neutral">${b.words.length} 词</span></div><p style="margin-top:12px">${b.description}</p><div class="book-bottom"><button class="text-btn" data-action="book-detail" data-id="${id}">查看单词</button><button class="button secondary sm" data-action="choose-book" data-id="${id}" ${!b.words.length?'disabled':''}>开始学习</button></div></article>`;}).join('')}</div><p class="footnote">切换词书保留学习记录。同一单词不会因换书重新计作新词。全量参考词表依据公开标签合并，并非官方逐词认证版本。</p>`;}
function rootsPage(){const inBook=new Set(ids());const roots=db.roots.filter(r=>(!rootQuery||`${r.label} ${r.meaning} ${r.words.map(w=>w.word).join(' ')}`.toLowerCase().includes(rootQuery.toLowerCase()))&&(rootFilter==='全部'||r.words.some(w=>inBook.has(w.word))));return `<div class="page-head"><div><h1>词根词典</h1><p>从核心含义出发，认识同一词族的不同表达。</p></div><span class="pill neutral">${db.roots.length} 组构词线索</span></div><div class="toolbar"><div class="tabs inset">${['全部','当前词书'].map(t=>`<button class="${rootFilter===t?'active':''}" data-action="root-filter" data-id="${t}">${t}</button>`).join('')}</div><div class="input-wrap">${icon('search')}<input id="root-search" placeholder="搜索词根、含义或单词" value="${esc(rootQuery)}" aria-label="搜索词根"></div></div><div class="notice">分别标注词根、前缀与后缀。词典关联与原创逐词讲解分开呈现，现代词义以释义和语境为准。</div><div id="root-results" class="root-grid">${rootCards(roots,inBook)}</div>`;}
function rootCards(roots,inBook=new Set(ids())){return roots.map(r=>`<button class="root-card" data-action="root" data-id="${r.id}"><div class="between"><span class="serif">${esc(r.label)}</span>${icon('chevron','muted')}</div><h3>${esc(r.meaning)}</h3><p>${esc(r.intro)}</p><span class="small">${r.words.length} 个相关词 · 本书 ${r.words.filter(w=>inBook.has(w.word)).length} 词</span></button>`).join('')||'<p>没有找到匹配的词根，试试其他关键词。</p>';}
function wordRow(w){const d=db.words[w];if(!d)return '';const p=state.progress[w];return `<button class="word-row" data-action="word" data-id="${esc(w)}"><div class="word-meta"><span class="word-name">${esc(w)}</span><p>${esc(d.meaning.split('\n').slice(0,2).join('；'))}</p></div>${d.root?'<span class="pill">词根</span>':''}${p?`<span class="pill neutral">${p.interval>=7?'较熟悉':'已学'}</span>`:''}${icon('chevron','muted')}</button>`;}
function searchPage(){return `<div class="page-head"><div><h1>找到你想理解的词。</h1><p>搜索英文或中文释义，查看词根、例句和学习记录。</p></div></div><div class="input-wrap" style="margin-bottom:20px">${icon('search')}<input id="word-search" placeholder="例如 transport，或「运输」" value="${esc(query)}" aria-label="搜索单词" autocomplete="off"></div><div id="search-results">${searchResults()}</div>`;}
function searchResults(){if(!query.trim())return empty('search','从一个单词开始','输入英文或中文，查找词库中的单词。');const q=query.toLowerCase().trim();const matches=Object.keys(db.words).filter(w=>w.includes(q)||db.words[w].meaning.includes(q)).sort((a,b)=>(a===q?-1:b===q?1:Number(b.startsWith(q))-Number(a.startsWith(q))));return matches.length?`<p class="small" style="margin-bottom:12px">找到 ${fmt(matches.length)} 个结果${matches.length>100?'，先展示前 100 个':''}</p><div class="word-list">${matches.slice(0,100).map(wordRow).join('')}</div>`:empty('search','暂未收录这个词','试试原形或其他关键词。未收录的词不会自动生成未经核验的解释。');}
function empty(ic,title,text,button=''){return `<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`;}
function favoritesPage(){return `<div class="page-head"><div><h1>留给下一次重逢。</h1><p>在单词卡上点收藏，把想再看一遍的词留在这里。</p></div><span class="pill neutral">${state.favorites.length} 词</span></div>${state.favorites.length?`<div class="word-list">${state.favorites.filter(w=>db.words[w]).map(wordRow).join('')}</div>`:empty('star','还没有收藏的单词','学习时遇到难词，点一下星星就能收藏。',`<button class="button" data-action="nav" data-id="search">去查一个词</button>`)}`;}
function statsPage(){const all=Object.values(state.progress),activeDays=new Set(state.events.map(e=>e.day)),attempts=state.attempts.slice(-200),first=new Map();for(const a of attempts){if(a.stage<2&&!first.has(a.session+':'+a.word))first.set(a.session+':'+a.word,a);}const independent=[...first.values()].filter(a=>!a.hinted),accuracy=independent.length?Math.round(independent.filter(a=>a.correct).length/independent.length*100):null;return `<div class="page-head"><h1>学习记录</h1><button class="button secondary" data-action="nav" data-id="settings">备份与同步</button></div><div class="stats-grid">${[['累计已学',all.length,'跨词书去重统计'],['较熟悉',all.filter(p=>p.interval>=7).length,'当前复习间隔 ≥ 7 天'],['学习天数',activeDays.size,'完成过单词训练的天数'],['首次独立回忆',accuracy===null?'—':accuracy+'%','最近 200 次练习中每词每轮首答，排除提示']].map(([name,value,note])=>`<div class="stat"><div class="stat-label">${name}</div><div class="stat-value">${fmtOrText(value)}</div><div class="stat-foot">${note}</div></div>`).join('')}</div><div class="stats-lower"><section class="panel"><h2>最近七天</h2>${weekChart()}</section><section class="panel"><h2>词书进度</h2>${db.books.filter(b=>b.level!=='ROOTS'&&b.kind!=='常用').map(b=>{const p=bookProgress(state,b.words);return `<div class="book-progress-row"><div class="progress-row"><span>${esc(b.title)}</span><strong>${p.learned} / ${fmt(p.total)}</strong></div><div class="progress"><i style="width:${p.percent}%"></i></div></div>`;}).join('')}</section></div><section class="panel"><h2>最近逐次回忆</h2><p class="footnote">核对后确认的每次判断会记录在这里；升级前未保存的逐次记录无法补造。</p>${state.attempts.length?`<div class="attempt-list">${state.attempts.slice(-30).reverse().map(a=>`<button class="attempt-row" data-action="word" data-id="${esc(a.word)}"><strong>${esc(a.word)}</strong><span>${stageName(a.stage)}</span><span class="${a.correct?'':'needed'}">${a.hinted?'使用提示':a.correct?'记对了':'记错了'}</span><small>${new Date(a.time).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></button>`).join('')}</div>`:'<p>完成核对后，这里会显示真实回忆记录。</p>'}</section>`;}

function fmtOrText(n){return typeof n==='number'?fmt(n):n;}
function settingsPage(){return `<div class="page-head"><h1>我的</h1></div><div class="profile-card"><div class="avatar">巧</div><div><h2>你的学习空间</h2><p>${OFFLINE?'免登录，进度保存在这台设备。':'同一账号同步进度，离线学习保存在本机。'}</p></div></div><div class="settings-grid"><section class="panel"><h2>学习偏好</h2><div class="setting-row"><div><label for="goal">每日新词</label><p>复习单独安排，不占新词数量。5–100 词。</p></div><input id="goal" type="number" min="5" max="100" value="${state.goal}"></div>${voiceSettingsHTML()}<div class="setting-row"><div><label for="auto-sound">自动朗读</label><p>单词出现时自动朗读，可随时点击重听。</p></div><input id="auto-sound" class="switch" type="checkbox" ${state.settings.sound?'checked':''}></div><div class="setting-row"><div><label for="all-review">复习所有词书的已学词</label><p>默认开启。关闭后只复习当前词书，旧书记录仍然保留。</p></div><input id="all-review" class="switch" type="checkbox" ${state.settings.maintainAll?'checked':''}></div><div class="tip"><strong>按真实回忆情况判断</strong>点“我认识”后核对答案，理解不对直接点“记错了”。提示会单独记录，稍后再独立回忆。</div></section><div class="stack">${OFFLINE?`<section class="panel"><h2>本机学习记录</h2><p>本版免登录，逐词进度、收藏和笔记保存在当前设备。通过导出与恢复备份，可以迁移到另一台设备。</p><p class="footnote">卸载应用、清除应用数据或浏览器站点数据会移除本机记录，请先导出备份。</p></section>`:`<section class="panel"><h2>电脑与手机同步</h2><p id="sync-status" role="status">${esc(syncStatus.message)}</p><p class="footnote">登录同一个账号后自动合并逐词进度、收藏、词表和笔记；正在做的练习留在当前设备。离线时继续学习，联网后同步。</p><div class="backup-actions"><button class="button secondary sm" data-action="sync-now">立即同步</button>${syncStatus.kind==='login'?'<a class="button secondary sm" href="/signin-with-chatgpt?returnTo=%2F" target="_top">登录同步</a>':''}</div></section>`}<section class="panel"><h2>备份与恢复</h2><p>备份包含逐词进度、回忆记录、收藏、笔记和本机未完成任务。恢复时先保留一份当前备份。</p><div class="backup-actions"><button class="button secondary sm" data-action="export">${icon('download')}导出备份</button><button class="button secondary sm" data-action="restore">${icon('upload')}恢复备份</button></div><input id="backup-file" type="file" accept=".json,application/json" hidden><button class="text-btn" data-action="export-previous">导出升级前的本机备份</button><p class="footnote">${OFFLINE?'本机存储有容量限制。':'云同步与离线存储均有容量限制。'}保存失败会明确提示；建议定期导出备份。逐次记录最多保留最近 50,000 条。</p></section><section class="panel"><h2>学习与复习</h2><p>同词根的单词依次出现。记对进入下一词，不认识或记错的词稍后再练；到期词自动加入复习。</p><p class="footnote">复习时间依据回忆表现和实际间隔计算，目标保留率不代表效果保证。</p><a class="source-link" href="https://github.com/open-spaced-repetition/ts-fsrs" target="_blank" rel="noopener noreferrer">查看算法来源与许可</a></section><section class="panel"><h2>${NATIVE?'离线使用':'像 App 一样使用'}</h2><p>${NATIVE?'词库与全部内置发音随安装包提供，断网也能学习和复习。':'手机浏览器菜单中选择“添加到主屏幕”。已缓存内容可离线使用，首次播放尚未缓存的发音需要网络。'}</p>${NATIVE?'':'<button class="text-btn" data-action="install">查看安装说明</button>'}</section><section class="panel"><div class="between"><h2>记巧</h2><span class="pill neutral">v1.0.0</span></div><p>${fmt(db.meta.wordCount)} 词 · ${fmt(db.meta.rootWordCount)} 词附构词关联 · ${fmt(db.meta.lessonWordCount)} 词附完整讲解</p><button class="text-btn" data-action="sources">内容来源与审核范围</button></section></div></div>`;}

function lessonHTML(w,{compact=false}={}){const d=db.words[w],l=d.lesson,r=rootOf(w);if(!l)return associationHTML(w);return `<div class="root-panel"><div class="between"><div class="eyebrow">词根 · 构词理解</div>${r?`<button class="text-btn" data-action="root" data-id="${r.id}" style="padding:0;font-size:12px">同根词</button>`:''}</div><div class="parts">${l.parts.map((p,i)=>`${i?'<span class="plus">＋</span>':''}<div class="part"><strong>${esc(p.text)}</strong><small>${esc(p.meaning)}</small></div>`).join('')}</div><p>${esc(l.explanation)}</p>${l.partsNote?`<p class="content-note">${esc(l.partsNote)}</p>`:""}</div>${!compact?`<div class="example"><div class="en">${esc(l.example)}</div><p class="zh">${esc(l.translation)}</p><div class="collocation">${esc(l.collocation)}</div></div>`:''}`;}
function stageName(stage){return ['认识与核对','独立回忆','看义回词','拼写测试'][stage];}
function shortMeaning(w){return db.words[w].meaning.split('\n').filter(x=>!/^\[/.test(x)).slice(0,2).join('；').slice(0,110);}
function studyContent(w){
 const d=db.words[w],l=d.lesson,r=rootOf(w);
 return `<div class="card-details">${r?`<section class="word-root-section"><h2>词根解释</h2>${lessonHTML(w,{compact:true})}</section>`:''}${l?`<section class="word-example-section"><h2>例句</h2><p class="example-en">${esc(l.example)}</p><p class="example-zh">${esc(l.translation)}</p></section><section class="word-collocation-section"><h2>常用搭配</h2><p>${esc(l.collocation)}</p></section>`:d.definition?`<section class="word-example-section"><h2>英文释义</h2><p class="dictionary-definition">${esc(d.definition)}</p></section>`:''}${d.dictionaryMeaning&&d.dictionaryMeaning!==d.meaning?`<details class="dictionary-more"><summary>更多词义</summary><p class="dictionary-definition">${esc(d.dictionaryMeaning)}</p></details>`:''}${notes[w]?`<section class="word-note-section"><h2>我的笔记</h2><p>${esc(notes[w])}</p></section>`:''}${(l?.source||r?.source)?`<a class="source-link" href="${esc(l?.source||r.source)}" target="_blank" rel="noopener noreferrer">词根参考资料</a>`:''}</div>`;
}

function associationHTML(w){const d=db.words[w],r=rootOf(w);return r?`<div class="association"><span class="pill neutral">词典构词关联</span><h3>${esc(r.label)} · ${esc(r.meaning)}</h3><p>源词典将这个词列入此构词家族。这个核心含义可以辅助理解，现代词义以本词释义为准。</p><p class="content-note">本条提供成员关联，尚无完整逐词拆解；不把相同字母直接当作词源证明。</p></div>`:`<div class="unannotated"><p>本词暂不作词根拆解，结合释义、英文解释与自己的使用场景记忆。</p>${d.definition?`<p class="dictionary-definition">${esc(d.definition)}</p>`:''}</div>`;}
function studyPage(){
 const s=state.session;if(!s)return empty('book','还没有开始学习','选择词书后，从首页开始。',`<button class="button" data-action="nav" data-id="today">回到首页</button>`);
 if(groupComplete(s))return groupPage();
 const feedback=s.feedback,task=currentTask(s),w=feedback?.word||task?.word;if(!w)return groupPage();
 const d=db.words[w],complete=s.words.filter(word=>s.items[word].done).length;
 return `<div class="study simple-card ${feedback?'card-answer':'card-question'}"><header class="study-top"><button data-action="pause" class="study-back" aria-label="暂存并返回">${icon('back')}<span>${complete}/${s.words.length}</span></button><span class="card-mode">${s.mode==='review'?'复习单词':'学习新词'}</span><div class="study-tools"><button data-action="favorite" data-id="${esc(w)}" class="${state.favorites.includes(w)?'saved':''}" aria-label="收藏单词" aria-pressed="${state.favorites.includes(w)}">${icon('star')}</button><button data-action="study-menu" aria-label="更多学习选项">${icon('settings')}</button></div></header><div class="card-progress" role="progressbar" aria-label="本次学习进度" aria-valuemin="0" aria-valuemax="${s.words.length}" aria-valuenow="${complete}"><i style="width:${complete/s.words.length*100}%"></i></div><div class="card-word-heading"><div class="study-word"><h1>${esc(w)}</h1><button data-action="speak" data-id="${esc(w)}" aria-label="朗读单词">${icon('volume')}</button></div><div class="study-phonetic">${d.phonetic?'/'+esc(d.phonetic)+'/':''}</div></div><div class="study-body">${feedback?`<div class="study-meaning">${esc(d.meaning)}</div>${studyContent(w)}`:'<div class="card-recall-prompt">回忆一下这个单词的意思</div>'}</div><div class="card-controls">${feedback?`<div class="card-feedback ${feedback.correct?'':'needed'}" role="status">${feedback.correct?'核对一下，是否记对了？':feedback.message}</div><div class="study-bottom">${feedback.pending&&feedback.correct?'<button class="button secondary" data-action="correct-answer">记错了</button>':''}<button class="button primary" data-action="continue">下一词</button></div>`:'<div class="recognition-actions"><button class="button secondary action-unknown" data-action="unknown">不认识</button><button class="button primary" data-action="recognize">我认识</button></div>'}</div><footer class="study-footer"><span>${complete} / ${s.words.length}</span><span>${feedback?'空格 下一词':'1 我认识 · 2 不认识 · P 发音'}</span></footer></div>`;
}
function groupPage(){
 const s=state.session,ws=s.words,checked=state.checkins.includes(localDay());
 return `<div class="group-summary"><div class="completion-symbol">${icon('check')}</div><h1>${s.mode==='review'?'本次复习完成':'本次学习完成'}</h1><p>下次需要复习的词会自动出现在复习中。</p><div class="summary-metrics"><div><strong>${ws.length}</strong><span>本次完成</span></div><div><strong>${ws.filter(w=>s.items[w].failures).length}</strong><span>经过重练</span></div><div><strong>${s.mode==='review'?todayStats(state).reviewCount:todayStats(state).newCount}</strong><span>${s.mode==='review'?'今日已复习':'今日已学'}</span></div></div><div class="summary-list"><div class="summary-list-head"><span>单词</span><span>下次复习</span></div>${ws.map(w=>`<button data-action="word" data-id="${esc(w)}"><span><i class="${s.items[w].failures?'needed':''}"></i>${esc(w)}</span><small>${state.progress[w]?.known?'已标熟':state.progress[w]?.interval+' 天后'}</small></button>`).join('')}</div><div class="summary-actions"><button class="button primary" data-action="checkin">${checked?'已打卡，返回首页':'完成并打卡'}</button><button class="quiet-action" data-action="finish">返回首页</button></div></div>`;
}

function render(){const pages={today:dashboard,plan:planPage,books:booksPage,roots:rootsPage,stats:statsPage,settings:settingsPage,search:searchPage,favorites:favoritesPage,study:studyPage};app.innerHTML=shell((pages[view]||dashboard)());document.title=`${label[view]} · 记巧`;refreshVoiceOptions();}

function openWord(w){if(!db.words[w])return;const d=db.words[w],p=state.progress[w];showModal('单词详情',`<div class="word-heading"><h1>${esc(w)}</h1><button class="icon-btn" data-action="speak" data-id="${esc(w)}" aria-label="朗读 ${esc(w)}">${icon('volume')}</button></div><div class="phonetic">${d.phonetic?'/'+esc(d.phonetic)+'/':''}</div><div class="meaning">${esc(d.meaning)}</div>${d.dictionaryMeaning&&d.dictionaryMeaning!==d.meaning?`<details class="dictionary-more"><summary>查看源词典的其他词义</summary><p class="dictionary-definition">${esc(d.dictionaryMeaning)}</p></details>`:""}${lessonHTML(w)}<div class="backup-actions"><button class="button secondary sm" data-action="favorite" data-id="${esc(w)}">${icon('star')}${state.favorites.includes(w)?'取消收藏':'收藏单词'}</button><button class="button secondary sm" data-action="add-custom" data-id="${esc(w)}">${icon('plus')}${state.custom.includes(w)?'已在自定义词表':'加入自定义词表'}</button><button class="text-btn" data-action="note" data-id="${esc(w)}">我的笔记</button></div>${p?.known?`<button class="text-btn" data-action="relearn" data-id="${esc(w)}">已标熟 · 重新加入复习</button>`:''}${notes[w]?`<div class="tip"><strong>我的笔记</strong>${esc(notes[w])}</div>`:''}${p?`<p class="footnote">累计完成 ${p.reps} 轮 · 下次复习 ${new Date(p.due).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}</p>`:'<p class="footnote">查看详情不会改变学习进度。</p>'}${rootOf(w)?`<a class="source-link" href="${esc(d.lesson?.source||rootOf(w).source)}" target="_blank" rel="noopener noreferrer">词根参考资料</a>`:''}`);modal.dataset.word=w;}
function openRoot(id){const r=db.roots.find(r=>r.id===id);if(!r)return;const pool=new Set(ids()),match=r.words.filter(w=>pool.has(w.word));showModal(`${r.label} · ${r.meaning}`,`<p>${esc(r.intro)}</p><div class="notice mt">当前词书收录 ${match.length} 个相关词。其他词供拓展查看，不会自动加入今日任务。</div>${match.length?`<button class="button full" data-action="study-root" data-id="${id}">学习本书中的相关词</button>`:''}<div class="word-list">${r.words.map(w=>wordRow(w.word)).join('')}</div><p class="footnote">解释用于帮助理解；原始词源和现代词义之间可能有长期演变。</p><a class="source-link" href="${esc(r.source)}" target="_blank" rel="noopener noreferrer">查看词根参考来源</a>`);}
function openBook(id){const b=getBook(id);if(!b)return;const p=bookProgress(state,b.words),coverage=b.words.filter(w=>db.words[w]?.root).length;showModal('词书详情',`<div class="book-detail-top">${cover(b)}<div><h2>${esc(b.title)}</h2><p>${esc(b.description)}</p></div></div><div class="details-metrics"><div><strong>${fmt(b.words.length)}</strong><span>词汇总数</span></div><div><strong>${p.learned}</strong><span>已经学过</span></div><div><strong>${coverage}</strong><span>附构词关联</span></div></div><div class="notice">${esc(b.criteria)}</div><button class="button full" data-action="choose-book" data-id="${id}" ${!b.words.length?'disabled':''}>${state.book===id?'学习这本词书':'选择这本词书'}</button><div class="input-wrap mt">${icon('search')}<input id="book-word-search" data-book="${id}" placeholder="在这本词书中查词" aria-label="词书内搜索"></div><div id="book-word-list" class="word-list">${b.words.slice(0,60).map(wordRow).join('')}</div><p id="book-word-count" class="footnote">${b.words.length>60?'显示前 60 词，可搜索其余单词。':'已显示全部单词。'}</p>`);}
function sources(){showModal('内容来源与审核范围',`<h3>词书</h3><p>基础词条来自 MIT 许可的 ECDICT。本版按公开考试标签和通用语料词频整理参考集合，不代表官方逐词核定词表，也未核验近年真题考频。</p><p>“进阶精选”按较低阶段标签排除筛选；标签不能区分一个词的基础义和考试引申义，因此不标作“考试重点”。每本词书详情公开筛选规则。</p><a class="source-link" href="https://github.com/skywind3000/ECDICT" target="_blank" rel="noopener noreferrer">ECDICT 来源与 MIT 许可</a><h3>构词内容</h3><p>${db.meta.rootCount} 组词根或词缀家族，${db.meta.rootWordCount} 个词附有明确成员关联，其中 ${db.meta.lessonWordCount} 个词附原创逐词讲解、例句和搭配。</p><p>词典关联只使用源文件明确列出的成员，经过有界排错；不按字母片段推测归类，也不声称全部成员已逐条人工校验。单词可关联多个家族，学习进度只保留一份。</p><p>逐词讲解保留参考链接与历史词形说明，联想与历史词源区别呈现。未附完整讲解的词会明确标注。</p><a class="source-link" href="./data/content-review.txt" target="_blank">本版内容核查记录</a><h3>复习与统计</h3><p>使用开源 FSRS 默认参数，依据回忆结果与真实时间安排间隔，目标保留率为 90%。本轮答错的词稍后重现，独立记对后更新长期安排；此目标不是记忆效果保证，不声称已拟合个人参数。</p><p>首次回忆正确率来自逐次记录，排除提示；升级前缺失的逐次记录不补造。</p><h3>发音</h3><p>内置 LJ Speech 美式女声，全部词条有独立音频，属于预先合成语音。词典音标没有统一口音标注，可能与音频不同；全部音频尚未逐词人工校听。</p><a class="source-link" href="./data/voice-notice.txt" target="_blank">音频来源与说明</a><h3>软件与隐私</h3><a class="source-link" href="./data/third-party-notices.txt" target="_blank">第三方来源与许可</a><br><a class="source-link" href="./data/ANDROIDX-LICENSE.txt" target="_blank">Android 开源组件许可</a>${OFFLINE?'<br><a class="source-link" href="./data/privacy.txt" target="_blank">离线分享版隐私说明</a>':''}<p class="footnote">整理日期：${db.meta.prepared}。日期表示本版内容整理时间，不代表原词典或语料更新到该日。</p>`);}

const deviceSpeaker=createSpeaker({synthesis:window.speechSynthesis,makeUtterance:text=>new SpeechSynthesisUtterance(text),onError:toast,onVoice:(voice,fallback)=>{const label=$('#voice-status');if(label)label.textContent='当前设备音色：'+voice.name+'（'+voice.lang+'）';if(fallback)toast('当前设备使用 '+voice.lang+' 英语音色。');}});
const builtinSpeaker=createRecordedSpeaker({makeAudio:src=>new Audio(src),onError:toast,onVoice:()=>{const label=$('#voice-status');if(label)label.textContent='正在播放：内置美式女声 · LJ Speech';}});
const speaker={stop(){deviceSpeaker.stop();builtinSpeaker.stop();},speak(word,options){if(state.settings.voiceSource==='system'){builtinSpeaker.stop();return deviceSpeaker.speak(word,options);}deviceSpeaker.stop();return builtinSpeaker.speak(word);}};
function speak(w){return speaker.speak(w,{accent:state.settings.accent,voiceId:state.settings.voiceId});}
function voiceSettingsHTML(){return `<div class="voice-settings"><label for="voice-source">发音方式</label><p>默认使用 App 自带音频，不需要安装系统英语语音。</p><div class="voice-select-row"><select id="voice-source" aria-label="发音方式"><option value="builtin" ${state.settings.voiceSource!=='system'?'selected':''}>内置美式女声</option><option value="system" ${state.settings.voiceSource==='system'?'selected':''}>设备英语语音（备用）</option></select><button class="button secondary" data-action="speak" data-id="transport">试听</button></div>${state.settings.voiceSource==='system'?`<div class="voice-select-row mt"><select id="accent" aria-label="设备语音口音"><option value="en-GB" ${state.settings.accent==='en-GB'?'selected':''}>设备英式</option><option value="en-US" ${state.settings.accent==='en-US'?'selected':''}>设备美式</option></select><select id="voice-id" aria-label="英语音色"><option value="">自动选择英语音色</option></select></div>`:''}<p id="voice-status" class="footnote" aria-live="polite"></p><p class="footnote">内置语音为预先生成的美式英语，不是真人词典录音；词条音标来自原词库。<a href="./data/voice-notice.txt" target="_blank">音频来源</a></p></div>`;}
function refreshVoiceOptions(){if(!state)return;const status=$('#voice-status');if(state.settings.voiceSource!=='system'){const m=builtinSpeaker.getManifest();if(status)status.textContent=m?'已内置 '+m.count+' 个单词发音 · LJ Speech 美式女声':'正在加载内置音频目录…';return;}const select=$('#voice-id');if(!select)return;const voices=englishVoices(window.speechSynthesis?.getVoices()||[]),exact=voices.filter(v=>v.lang.replaceAll('_','-').toLowerCase()===state.settings.accent.toLowerCase()),pool=exact.length?exact:voices;select.innerHTML='<option value="">自动选择英语音色</option>'+pool.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}</option>`).join('');select.value=state.settings.voiceId||'';const voice=selectVoice(voices,state.settings.accent,state.settings.voiceId);if(status)status.textContent=voice?'当前设备音色：'+voice.name+'（'+voice.lang+'）':'当前浏览器未提供英语音色，请切换到内置美式女声。';}
window.speechSynthesis?.addEventListener?.('voiceschanged',refreshVoiceOptions);
function resetCard(){speaker.stop();cardStarted=Date.now();render();window.scrollTo(0,0);const t=currentTask(state.session);if(state.settings.sound&&t)speak(t.word);}
function start(mode='new',rootId){
 if(storageBlocked){toast('原学习记录读取异常，已保留；请先恢复备份。');return;}
 closeModal();const wanted=mode==='review'?'review':'new',key=wanted+':'+state.book+(rootId?':'+rootId:'');
 if(state.session){reconcileSession(state,state.session);if(!sessionComplete(state.session)){if(sessionKey(state.session)===key){save();view='study';resetCard();return;}state.parked[sessionKey(state.session)]=state.session;}}
 if(state.parked[key]){const pending=state.parked[key];delete state.parked[key];reconcileSession(state,pending);if(!sessionComplete(pending)){state.session=pending;save();view='study';resetCard();return;}}
 state.session=null;const b=activeBook();let pool=ids();if(rootId)pool=db.roots.find(r=>r.id===rootId).words.map(w=>w.word).filter(w=>pool.includes(w));
 if(mode==='review'&&state.settings.maintainAll)pool=[...new Set([...pool,...Object.keys(state.progress)])];
 state.session=makeSession(state,pool,db.words,{mode:mode==='review'?'review':'new',title:rootId?'词根专项':b.title,rootId});
 if(!state.session){const saved=Object.values(state.parked).find(s=>!sessionComplete(s));if(saved){state.session=saved;delete state.parked[sessionKey(saved)];}save();toast(mode==='review'?'暂无到期复习。':todayStats(state).newCount>=state.goal?'今日目标已完成，可在学习设置中调整。':'本书新词已学完。');navigate('today');return;}
 if(wanted==='new'){const last=state.session.words.at(-1);state.focus[state.book]=db.words[last]?.studyRoot||'';}save();view='study';resetCard();
}
function chooseBook(id){const b=getBook(id);if(!b||!b.words.length){toast('词表为空，请先添加单词。');return;}state.book=id;state.settingsUpdated=Date.now();save();closeModal();navigate('plan');toast('已选择「'+b.title+'」，已有进度保留');}
function submitAnswer(correct,known=false){prepareAnswer(state,correct,{known,duration:Math.min(3600000,Date.now()-cardStarted)});save();render();window.scrollTo(0,0);}
function downloadBackup(text,filename){
 if(NATIVE&&window.JiQiaoAndroid?.exportBackup){window.JiQiaoAndroid.exportBackup(text,filename);return;}
 const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份文件已生成');
}
function exportBackup(){downloadBackup(JSON.stringify({...state,notes,noteTimes,exportedAt:new Date().toISOString()},null,2),`记巧备份-${localDay()}.json`);}
window.JiQiaoNavigation={goBack(){if(modal.open){closeModal();return true;}if(view!=='today'){save();navigate('today');return true;}return false;},backupResult(message){toast(message);}};

function importWords(){showModal('导入自己的词表',`<p>粘贴英文单词，每行一个，也可以用逗号分隔。将匹配本版已有词库，不会覆盖你的学习记录。</p><textarea id="import-text" placeholder="transport\nimport\nexport" aria-label="要导入的单词"></textarea><button class="button full" data-action="preview-import">检查词表</button><div id="import-result"></div>`);}
let importMatched=[];
function previewImport(){const text=$('#import-text').value;if(text.length>200000){toast('内容过长，请分批导入。');return;}const entries=[...new Set(text.toLowerCase().split(/[\n,，;；\t\r]+/).map(x=>x.trim()).filter(Boolean))];importMatched=entries.filter(w=>db.words[w]);const missing=entries.filter(w=>!db.words[w]);$('#import-result').innerHTML=`<div class="notice mt">匹配 ${importMatched.length} 词，未匹配 ${missing.length} 词。${missing.length?`<br>未匹配：${esc(missing.slice(0,15).join('、'))}${missing.length>15?'…':''}`:''}</div>${importMatched.length?`<button class="button full" data-action="confirm-import">加入自定义词表</button>`:''}`;}
async function loadBackup(file){if(!file)return;if(file.size>10000000){toast('备份过大，请选择 10 MB 以内的记巧备份。');return;}try{const raw=JSON.parse(await file.text());const restored=normalizeState(raw);const restoredNotes={};for(const [w,n] of Object.entries(raw.notes||{})){if(db.words[w]&&typeof n==='string')restoredNotes[w]=n.slice(0,4000);}pendingBackup={state:restored,notes:restoredNotes,noteTimes:raw.noteTimes||{}};showModal('恢复学习备份',`<p>备份中包含 ${Object.keys(restored.progress).length} 个已学单词、${restored.favorites.length} 个收藏和 ${restored.custom.length} 个自定义词条。</p><div class="notice mt">恢复会替换本机记录与笔记；${OFFLINE?'备份不会自动合并，请先保存当前记录。':'联网同步时与云端按更新时间合并。'}建议先导出当前记录。</div><div class="backup-actions"><button class="button secondary" data-action="export">先导出当前记录</button><button class="button" data-action="confirm-restore">确认恢复备份</button></div>`);}catch{toast('文件格式不正确，未更改现有记录。');}}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='nav'){closeModal();navigate(id);if(id==='search')$('#word-search')?.focus();}
 else if(a==='close')closeModal();
 else if(a==='start')start(el.dataset.mode);
 else if(a==='resume'){if(state.session)reconcileSession(state,state.session);if(!state.session||sessionComplete(state.session)){const pending=Object.entries(state.parked).find(([,s])=>{reconcileSession(state,s);return !sessionComplete(s);});if(pending){state.session=pending[1];delete state.parked[pending[0]];}}if(!state.session||sessionComplete(state.session)){toast('未完成任务中的词已在其他任务完成。');navigate('today');return;}state.book=state.session.book;save();view='study';resetCard();}
 else if(a==='theme'){const ts=['mist','rose','cloud'];state.settings.theme=ts[(ts.indexOf(state.settings.theme)+1)%3];save();render();}
 else if(a==='goal'){showModal('每日学习量',`<p>每日新词数量</p><input id="goal" type="number" min="5" max="100" value="${state.goal}"><p class="footnote">修改后生效于下一次新建任务。</p>`);}
 else if(a==='book-filter'){bookFilter=id;render();}
 else if(a==='root-filter'){rootFilter=id;render();}
 else if(a==='choose-book')chooseBook(id);
 else if(a==='book-detail')openBook(id);
 else if(a==='root')openRoot(id);
 else if(a==='word'){if(view==='study'&&currentTask(state.session)){useHint(state.session);save();}openWord(id);}
 else if(a==='sources')sources();
 else if(a==='speak')speak(id);
 else if(a==='study-root')start('root',id);
 else if(a==='pause'){closeModal();save();navigate('today');}
 else if(a==='recognize')submitAnswer(true);
 else if(a==='unknown')submitAnswer(false);
 else if(a==='known')showModal('标记为熟知',`<p>将「${esc(currentTask(state.session).word)}」标为熟知后，它将退出常规复习。你可以在单词详情中重新加入。</p><button class="button primary full" data-action="confirm-known">确认熟知</button>`);
 else if(a==='confirm-known'){closeModal();submitAnswer(true,true);}
 else if(a==='correct-answer'){correctPending(state.session);save();render();}
 else if(a==='continue'){continueSession(state.session,state);save();resetCard();}
 else if(a==='checkin'){if(!state.checkins.includes(localDay()))state.checkins.push(localDay());state.session=null;save();navigate('today');toast('今日学习已打卡');}
 else if(a==='study-menu')showModal('学习选项',`<div class="content-links"><button data-action="pause">暂存并返回</button><button data-action="note" data-id="${esc(state.session.feedback?.word||currentTask(state.session)?.word)}">记个笔记</button>${currentTask(state.session)?.stage===0?'<button data-action="known">标记为熟知</button>':''}<button data-action="sources">内容来源</button></div>`);

 else if(a==='finish'){state.session=null;save();navigate('today');}
 else if(a==='favorite'){state.collectionChanges['favorites:'+id]={time:Date.now(),present:!state.favorites.includes(id)};state.favorites=state.favorites.includes(id)?state.favorites.filter(w=>w!==id):[...state.favorites,id];save();if(modal.open)openWord(id);else render();toast(state.favorites.includes(id)?'已加入生词收藏':'已取消收藏');}
 else if(a==='relearn'){const p=state.progress[id];if(p){p.known=false;p.due=Date.now();p.last=Date.now();}save();openWord(id);toast('已重新加入复习');}
 else if(a==='add-custom'){if(!state.custom.includes(id))state.custom.push(id);state.collectionChanges['custom:'+id]={time:Date.now(),present:true};save();openWord(id);toast('已加入自定义词表');}
 else if(a==='note'){if(view==='study'&&currentTask(state.session)){useHint(state.session);save();}showModal('我的笔记 · '+id,`<p>可以记录自己的联想、易错点或释义修正。</p><textarea id="note-text" maxlength="4000" aria-label="单词笔记">${esc(notes[id]||'')}</textarea><button class="button full" data-action="save-note" data-id="${esc(id)}">保存笔记</button>`);}
 else if(a==='save-note'){notes[id]=$('#note-text').value.trim();noteTimes[id]=Date.now();try{localStorage.setItem('rootwise.note-times.v1',JSON.stringify(noteTimes));localStorage.setItem('rootwise.notes.v1',JSON.stringify(notes));}catch{toast('笔记暂无法保存到浏览器，请导出备份。');}save();closeModal();render();toast('笔记已更新');}
 else if(a==='export')exportBackup();
 else if(a==='restore')$('#backup-file').click();
 else if(a==='confirm-restore'&&pendingBackup){state=pendingBackup.state;notes=pendingBackup.notes;noteTimes=pendingBackup.noteTimes;storageBlocked=false;filterState();save();try{localStorage.setItem('rootwise.notes.v1',JSON.stringify(notes));localStorage.setItem('rootwise.note-times.v1',JSON.stringify(noteTimes));}catch{}pendingBackup=null;closeModal();navigate('today');if(!OFFLINE){if(!syncer){syncer=createSync({getLocal:()=>({state,notes,noteTimes}),applyMerged:applyCloud,onStatus:setSyncStatus});}syncer.run();}toast('备份已恢复');}
 else if(a==='import-words')importWords();
 else if(a==='preview-import')previewImport();
 else if(a==='confirm-import'){for(const w of importMatched)state.collectionChanges['custom:'+w]={time:Date.now(),present:true};state.custom=[...new Set([...state.custom,...importMatched])];save();closeModal();navigate('books');toast(`自定义词表现有 ${state.custom.length} 个词`);}
 else if(a==='sync-now')syncer?.run();
 else if(a==='export-previous'){const raw=localStorage.getItem('rootwise.before-v3');if(!raw){toast('当前设备没有升级前的备份。');return;}downloadBackup(raw,'记巧升级前备份.json');}
 else if(a==='install')showModal('添加到主屏幕',`<h3>iPhone / iPad</h3><p>使用 Safari 打开本站，点击分享按钮，选择“添加到主屏幕”。</p><h3>Android</h3><p>在 Chrome 或 Edge 的菜单中选择“安装应用”或“添加到主屏幕”，具体名称取决于浏览器。</p><h3>电脑</h3><p>Chrome / Edge 支持时，可使用地址栏安装图标。也可以收藏网址，直接在浏览器中使用。</p><div class="notice mt">${OFFLINE?'分享版免登录，记录保存在本机；通过备份迁移设备。':'同一账号登录后自动同步进度；断网时保存在本机，联网后合并。'}网页版不会自动下载所有发音，可在学习前联网播放并缓存；APK 已包含全部内置发音。</div>`);
});
document.addEventListener('input',e=>{if(e.target.id==='word-search'){query=e.target.value;$('#search-results').innerHTML=searchResults();}else if(e.target.id==='root-search'){rootQuery=e.target.value;const pool=new Set(ids());$('#root-results').innerHTML=rootCards(db.roots.filter(r=>(rootFilter==='全部'||r.words.some(w=>pool.has(w.word)))&&`${r.label} ${r.meaning} ${r.words.map(w=>w.word).join(' ')}`.toLowerCase().includes(rootQuery.toLowerCase())),pool);}else if(e.target.id==='book-word-search'){const b=getBook(e.target.dataset.book),q=e.target.value.toLowerCase().trim(),matched=b.words.filter(w=>w.includes(q)||db.words[w].meaning.includes(q));$('#book-word-list').innerHTML=matched.slice(0,100).map(wordRow).join('')||'<p style="padding:20px">没有匹配的单词。</p>';$('#book-word-count').textContent=`匹配 ${matched.length} 词${matched.length>100?'，显示前 100 词':''}`;}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='goal'){state.goal=Math.max(5,Math.min(100,Math.round(Number(e.target.value)||15)));e.target.value=state.goal;save();toast('每日新词目标已更新');}else if(id==='voice-source'){speaker.stop();state.settings.voiceSource=e.target.value==='system'?'system':'builtin';save();render();}else if(id==='accent'){speaker.stop();state.settings.accent=e.target.value;state.settings.voiceId='';save();refreshVoiceOptions();}else if(id==='voice-id'){speaker.stop();state.settings.voiceId=e.target.value;save();refreshVoiceOptions();}else if(id==='auto-sound'){state.settings.sound=e.target.checked;save();if(state.settings.sound)speak('hello');}else if(id==='all-review'){state.settings.maintainAll=e.target.checked;save();}else if(id==='backup-file')loadBackup(e.target.files[0]);});

document.addEventListener('change',e=>{if(!state)return;if(['goal','voice-source','accent','voice-id','auto-sound','all-review'].includes(e.target.id)){state.settingsUpdated=Date.now();save();}});


document.addEventListener('keydown',e=>{
 if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||modal.open||e.ctrlKey||e.metaKey||e.altKey)return;
 if(e.key==='/'){e.preventDefault();navigate('search');$('#word-search').focus();return;}
 if(view!=='study'||!state.session)return;
 if(e.code==='Space'){e.preventDefault();if(state.session.feedback)document.querySelector('[data-action="continue"]')?.click();return;}
 const task=currentTask(state.session);if(!task)return;
 if(e.key==='1')document.querySelector('[data-action="recognize"]')?.click();else if(e.key==='2')document.querySelector('[data-action="unknown"]')?.click();else if(e.key.toLowerCase()==='p')speak(task.word);
});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function filterState(){
 state.favorites=state.favorites.filter(w=>db.words[w]);state.custom=state.custom.filter(w=>db.words[w]);if(!getBook(state.book))state.book='cet4-all';
 const clean=s=>{if(!s)return null;s.words=s.words.filter(w=>db.words[w]);if(!s.words.length)return null;s.groups=[s.words];s.group=0;s.groupSize=s.words.length;s.queue=s.queue.filter(w=>db.words[w]&&!s.items[w].done);if(s.feedback&&!db.words[s.feedback.word])s.feedback=null;reorderLegacyNewSession(s,db.words);return s;};
 state.session=clean(state.session);for(const [key,s] of Object.entries(state.parked)){const next=clean(s);if(next)state.parked[key]=next;else delete state.parked[key];}
}
function applyCloud(merged){const previous=state.session?.feedback?.word||currentTask(state.session)?.word;state=merged.state;notes=merged.notes;noteTimes=merged.noteTimes;filterState();if(state.session)reconcileSession(state,state.session);for(const s of Object.values(state.parked))reconcileSession(state,s);save(false);try{localStorage.setItem('rootwise.notes.v1',JSON.stringify(notes));localStorage.setItem('rootwise.note-times.v1',JSON.stringify(noteTimes));}catch{storageOkay=false;}if(view==='study'){const next=state.session?.feedback?.word||currentTask(state.session)?.word;if(previous!==next)resetCard();}else if(!modal.open)render();}
function setSyncStatus(kind,message){syncStatus={kind,message};const element=$('#sync-status');if(element)element.textContent=message;if(view==='settings'&&kind==='login')render();}
async function boot(){try{
 const [res,audioRes]=await Promise.all([fetch('./data/lexicon.json'),fetch('./data/audio.json').catch(()=>null)]);if(audioRes?.ok)builtinSpeaker.setManifest(await audioRes.json());if(!res.ok)throw Error('词库加载失败');db=await res.json();state=initialState();
 try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){let parsed;try{parsed=JSON.parse(raw);}catch{storageBlocked=true;try{if(!localStorage.getItem('rootwise.before-v3'))localStorage.setItem('rootwise.before-v3',raw);}catch{}throw Error('记录格式异常');}if(parsed.schema!==3&&!localStorage.getItem('rootwise.before-v3')){const oldNotes=JSON.parse(localStorage.getItem('rootwise.notes.v1')||'{}');localStorage.setItem('rootwise.before-v3',JSON.stringify({...parsed,notes:oldNotes}));}state=normalizeState(parsed);}const n=JSON.parse(localStorage.getItem('rootwise.notes.v1')||'{}');if(n&&typeof n==='object')for(const [w,v] of Object.entries(n))if(db.words[w]&&typeof v==='string')notes[w]=v.slice(0,4000);noteTimes=JSON.parse(localStorage.getItem('rootwise.note-times.v1')||'{}');if(!noteTimes||typeof noteTimes!=='object'||Array.isArray(noteTimes))noteTimes={};}
 catch{storageBlocked=true;toast('原有记录读取异常，已保留，请到“我的”恢复备份。');}
 filterState();if(state.session)reconcileSession(state,state.session);save(false);render();
 if(!storageBlocked&&!OFFLINE){syncer=createSync({getLocal:()=>({state,notes,noteTimes}),applyMerged:applyCloud,onStatus:setSyncStatus});syncer.run();window.addEventListener('online',()=>syncer.run());document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncer.run();});window.addEventListener('focus',()=>syncer.queue());}
 if(!NATIVE&&'serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
 }catch(err){app.innerHTML=`<div class="loading error"><div class="brand-symbol"><img src="./icon.svg" alt=""></div><h1>暂时没有打开词库</h1><p>${NATIVE?'请关闭后重新打开；若仍无法加载，请保留备份并重新安装完整 APK。':'请连接网络后重新打开。首次使用需要下载词库。'}</p><button class="button" onclick="location.reload()">重新加载</button><small>${esc(err.message)}</small></div>`;}}

boot();
